# Extra safe token repairs that may occur in multiple episodes after suffixes/first-pass edits.
TOK={
'ازتراریه':'اضطراریه','استراریه':'اضطراریه','استرالی':'اضطراری','استرار؟':'اضطرار؟','پیشبینیه':'پیش‌بینیه','پیشبینی':'پیش‌بینی',
'کارافرینیه':'کارآفرینیه','کارافرین':'کارآفرین','کارافرینی':'کارآفرینی','روانندگی':'رانندگی','راندگی':'رانندگی','شایستهی':'شایستگی',
'ریسکایی':'ریسک‌هایی','ریسکا':'ریسک‌ها','انترنت':'اینترنت','انترنتی':'اینترنتی','انترنتیه':'اینترنتیه','کارگوزار':'کارگزار','کارگوزاری':'کارگزاری',
'احساب':'حساب','نقض شوندگیش':'نقدشوندگیش','نقض شونده':'نقدشونده','تلاست':'طلاست','دوشفاری':'دشواری','دوشبار':'دشوار','نهتا':'نه‌تا',
}

def apply(text, mapping, log):
    # exact longer phrases first
    for old,new in sorted(mapping.items(), key=lambda x:len(x[0]), reverse=True):
        n=text.count(old)
        if n:
            text=text.replace(old,new); log.append((old,new,n))
    return text

logs={}
for ep in range(1,14):
    p=OUT/f'{ep}.md'; text=p.read_text(encoding='utf-8'); log=[]
    text=apply(text,P.get(ep,{}),log)
    text=apply(text,TOK,log)
    p.write_text(text,encoding='utf-8'); logs[ep]=log

# Append to existing provenance report.
existing=REPORT.read_text(encoding='utf-8') if REPORT.exists() else '# گزارش پاک‌سازی ASR — خانه تو\n'
lines=[existing.rstrip(),'','---','','# دور دوم پاک‌سازی هدفمند','']
for ep in range(1,14):
    total=sum(n for _,_,n in logs[ep]); lines.append(f'## قسمت {ep} — {total} جایگزینی دور دوم')
    for a,b,n in logs[ep]: lines.append(f'- `{a}` → `{b}` × {n}')
    lines.append('')
REPORT.write_text('\n'.join(lines),encoding='utf-8')
print({ep:sum(n for _,_,n in v) for ep,v in logs.items()})
